unsafe fn segment_solve(
    n: i32,
    x: f64,
    lower: f64,
    u: *mut f64,
    w: *mut f64,
    breakpoint: f64,
    fn1: Option<QuadratureFunction>,
    fn2: Option<QuadratureFunction>,
) -> i32 {
    let mut error: i32 = 0;
    if x <= breakpoint {
        error = fn1.expect("non-null function pointer")(n, x, lower, u, w);
    } else {
        error = fn2.expect("non-null function pointer")(n, x, lower, u, w);
    }
    if error != 0 {
        error = CINTlrys_schmidt(n, x, lower, u, w);
    }
    error
}
pub unsafe fn CINTrys_roots(nroots: i32, x: f64, u: *mut f64, w: *mut f64) {
    if x <= 3e-7f64 {
        let off: i32 = nroots * (nroots - 1_i32) / 2_i32;
        let mut i: i32 = 0;
        i = 0_i32;
        while i < nroots {
            *u.offset(i as isize) =
                POLY_SMALLX_R0[(off + i) as usize] + POLY_SMALLX_R1[(off + i) as usize] * x;
            *w.offset(i as isize) =
                POLY_SMALLX_W0[(off + i) as usize] + POLY_SMALLX_W1[(off + i) as usize] * x;
            i += 1;
            i;
        }
        return;
    } else if x >= (35_i32 + nroots * 5_i32) as f64 {
        let off_0: i32 = nroots * (nroots - 1_i32) / 2_i32;
        let mut i_0: i32 = 0;
        let mut rt: f64 = 0.;
        let t: f64 = sqrt(0.785_398_163_397_448_3_f64 / x);
        i_0 = 0_i32;
        while i_0 < nroots {
            rt = POLY_LARGEX_RT[(off_0 + i_0) as usize];
            *u.offset(i_0 as isize) = rt / (x - rt);
            *w.offset(i_0 as isize) = POLY_LARGEX_WW[(off_0 + i_0) as usize] * t;
            i_0 += 1;
            i_0;
        }
        return;
    }
    let mut err: i32 = 0;
    match nroots {
        1 => {
            err = rys_root1(x, u, w);
        }
        2 => {
            err = rys_root2(x, u, w);
        }
        3 => {
            err = rys_root3(x, u, w);
        }
        4 => {
            err = rys_root4(x, u, w);
        }
        5 => {
            err = rys_root5(x, u, w);
        }
        6 | 7 => {
            err = segment_solve(
                nroots,
                x,
                0.0f64,
                u,
                w,
                11_f64,
                Some(CINTrys_jacobi as unsafe fn(i32, f64, f64, *mut f64, *mut f64) -> i32),
                Some(CINTrys_schmidt as unsafe fn(i32, f64, f64, *mut f64, *mut f64) -> i32),
            );
        }
        8 => {
            err = segment_solve(
                nroots,
                x,
                0.0f64,
                u,
                w,
                11_f64,
                Some(CINTrys_jacobi as unsafe fn(i32, f64, f64, *mut f64, *mut f64) -> i32),
                Some(CINTlrys_schmidt as unsafe fn(i32, f64, f64, *mut f64, *mut f64) -> i32),
            );
        }
        9 => {
            err = segment_solve(
                nroots,
                x,
                0.0f64,
                u,
                w,
                10_f64,
                Some(CINTlrys_jacobi as unsafe fn(i32, f64, f64, *mut f64, *mut f64) -> i32),
                Some(CINTlrys_laguerre as unsafe fn(i32, f64, f64, *mut f64, *mut f64) -> i32),
            );
        }
        10 | 11 => {
            err = segment_solve(
                nroots,
                x,
                0.0f64,
                u,
                w,
                18_f64,
                Some(CINTlrys_jacobi as unsafe fn(i32, f64, f64, *mut f64, *mut f64) -> i32),
                Some(CINTlrys_laguerre as unsafe fn(i32, f64, f64, *mut f64, *mut f64) -> i32),
            );
        }
        12 => {
            err = segment_solve(
                nroots,
                x,
                0.0f64,
                u,
                w,
                22_f64,
                Some(CINTlrys_jacobi as unsafe fn(i32, f64, f64, *mut f64, *mut f64) -> i32),
                Some(CINTlrys_laguerre as unsafe fn(i32, f64, f64, *mut f64, *mut f64) -> i32),
            );
        }
        _ => {
            err = segment_solve(
                nroots,
                x,
                0.0f64,
                u,
                w,
                50_f64,
                Some(CINTlrys_jacobi as unsafe fn(i32, f64, f64, *mut f64, *mut f64) -> i32),
                Some(CINTlrys_laguerre as unsafe fn(i32, f64, f64, *mut f64, *mut f64) -> i32),
            );
        }
    }
    if err != 0 {
        eprintln!("rys_roots fails: nroots={} x={}", nroots, x);
        std::process::exit(err);
    }
}
unsafe fn segment_solve1(
    n: i32,
    x: f64,
    lower: f64,
    u: *mut f64,
    w: *mut f64,
    lower_bp1: f64,
    lower_bp2: f64,
    breakpoint: f64,
    fn1: Option<QuadratureFunction>,
    fn2: Option<QuadratureFunction>,
    fn3: Option<QuadratureFunction>,
) -> i32 {
    let mut error: i32 = 0;
    if lower < lower_bp1 {
        if x <= breakpoint {
            error = fn1.expect("non-null function pointer")(n, x, lower, u, w);
        } else {
            error = fn2.expect("non-null function pointer")(n, x, lower, u, w);
        }
    } else if lower < lower_bp2 {
        error = fn3.expect("non-null function pointer")(n, x, lower, u, w);
    } else {
        return 1_i32;
    }
    if error != 0 {
        error = CINTlrys_schmidt(n, x, lower, u, w);
    }
    error
}
