unsafe fn _rdk_rys_roots(
    nroots: i32,
    fmt_ints: *mut f64,
    roots: *mut f64,
    weights: *mut f64,
) -> i32 {
    let mut i: i32 = 0;
    let mut k: i32 = 0;
    let mut j: i32 = 0;
    let mut order: i32 = 0;
    let nroots1: i32 = nroots + 1_i32;
    let mut rt: [f64; 1056] = [0.; 1056];
    let cs: *mut f64 = rt.as_mut_ptr().offset(nroots1 as isize);
    let mut a: *mut f64 = std::ptr::null_mut::<f64>();
    let mut root: f64 = 0.;
    let mut poly: f64 = 0.;
    let mut dum: f64 = 0.;
    if *fmt_ints.offset(0_isize) == 0 as f64 {
        k = 0_i32;
        while k < nroots {
            *roots.offset(k as isize) = 0 as f64;
            *weights.offset(k as isize) = 0 as f64;
            k += 1;
            k;
        }
        return 0_i32;
    }
    if nroots == 1_i32 {
        *roots.offset(0_isize) =
            *fmt_ints.offset(1_isize) / (*fmt_ints.offset(0_isize) - *fmt_ints.offset(1_isize));
        *weights.offset(0_isize) = *fmt_ints.offset(0_isize);
        return 0_i32;
    }
    let mut error: i32 = R_dsmit(cs, fmt_ints, nroots1);
    if error != 0 {
        return 1_i32;
    }
    error = _CINT_polynomial_roots(rt.as_mut_ptr(), cs, nroots);
    if error != 0 {
        return error;
    }
    k = 0_i32;
    while k < nroots {
        root = rt[k as usize];
        if root == 1_f64 {
            *roots.offset(k as isize) = 0 as f64;
            *weights.offset(k as isize) = 0 as f64;
        } else {
            dum = 1_f64 / *fmt_ints.offset(0_isize);
            j = 1_i32;
            while j < nroots {
                order = j;
                a = cs.offset((j * nroots1) as isize);
                poly = *a.offset(order as isize);
                i = 1_i32;
                while i <= order {
                    poly = poly * root + *a.offset((order - i) as isize);
                    i += 1;
                    i;
                }
                dum += poly * poly;
                j += 1;
                j;
            }
            *roots.offset(k as isize) = root / (1_f64 - root);
            *weights.offset(k as isize) = 1_f64 / dum;
        }
        k += 1;
        k;
    }
    0_i32
}
pub unsafe fn CINTrys_schmidt(
    nroots: i32,
    x: f64,
    lower: f64,
    roots: *mut f64,
    weights: *mut f64,
) -> i32 {
    let mut fmt_ints: [f64; 64] = [0.; 64];
    if lower == 0 as f64 {
        gamma_inc_like(fmt_ints.as_mut_ptr(), x, nroots * 2_i32);
    } else {
        fmt_erfc_like(fmt_ints.as_mut_ptr(), x, lower, nroots * 2_i32);
    }
    _rdk_rys_roots(nroots, fmt_ints.as_mut_ptr(), roots, weights)
}
